const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g AGENTS.md -g composer.json -g composer.lock -g '.github/**' -g '*split*' -g '*release*' -g '*README*' -g '*LICENSE*' -g 'Makefile*' -g 'justfile*' -g '!vendor' -g '!**/vendor/**' -g '!node_modules'","max_output_tokens":6000}),
  tools.exec_command({cmd:"git status --short && git branch --show-current && git remote -v && ls -la .github && gh auth status","max_output_tokens":4000}),
  tools.exec_command({cmd:"cat /Users/ab/.agents/skills/find-docs/SKILL.md","max_output_tokens":8000})
]); results.forEach((r,i)=>text({i,...r}));
text(ALL_TOOLS.filter(x=>/search/.test(x.name)).map(x=>({name:x.name,description:x.description.slice(0,150)})));

